package com.youriptv.app.data

import java.net.URI

/**
 * An M3U link generated by an Xtream panel (`/get.php?username=…`) shares the account's
 * connection limit, which only the Xtream API reports. Borrow it from a matching Xtream playlist.
 */
object ConnectionLimit {

    fun sameAccount(first: Playlist, second: Playlist): Boolean {
        if (first.id != 0L && first.id == second.id) return true
        val firstEndpoint = endpoint(first.url) ?: return false
        val secondEndpoint = endpoint(second.url) ?: return false
        val firstUser = accountUser(first) ?: return false
        val secondUser = accountUser(second) ?: return false
        return firstEndpoint == secondEndpoint && firstUser == secondUser
    }

    fun effective(p: Playlist, all: List<Playlist>): Int {
        if (p.maxConnections > 0 || p.type != SourceType.M3U) return p.maxConnections
        val m3u = endpoint(p.url) ?: return 0
        val user = queryParam(p.url, "username") ?: return 0
        return all.firstOrNull {
            it.type == SourceType.XTREAM && it.maxConnections > 0 &&
                it.username == user && endpoint(it.url) == m3u
        }?.maxConnections ?: 0
    }

    private fun accountUser(playlist: Playlist): String? =
        (if (playlist.type == SourceType.XTREAM) playlist.username else queryParam(playlist.url, "username"))
            ?.takeIf { it.isNotBlank() }

    private fun endpoint(url: String): String? = runCatching {
        val u = URI(url.trim())
        val host = u.host?.lowercase() ?: return null
        val port = if (u.port > 0) u.port else if (u.scheme.equals("https", true)) 443 else 80
        "$host:$port"
    }.getOrNull()

    private fun queryParam(url: String, name: String): String? = runCatching {
        URI(url.trim()).rawQuery?.split('&')?.firstNotNullOfOrNull { kv ->
            val i = kv.indexOf('=')
            if (i > 0 && kv.substring(0, i) == name) java.net.URLDecoder.decode(kv.substring(i + 1), "UTF-8") else null
        }
    }.getOrNull()
}
